    "시트": {
      "type": "object",
      "properties": {
        "이름": {
          "type": "string"
        }
      },
      "required": [
        "이름"
      ],
      "additionalProperties": false
    }
  },
  "required": [
    "시트"
  ],
  "additionalProperties": false
}

